// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PrivateBank c;
    function setUp() public { c = new PrivateBank(address(new Log())); }
    function testFuzz_property(uint256 amount, uint8 actorSeed) public {
        vm.assume(amount <= VALUE_CAP);
        address actor = address(uint160(uint256(keccak256(abi.encode(actorSeed)))) | uint160(0x1000000000000000000000000000000000000000));
        amount = bound(amount, 1 ether, type(uint96).max);
        vm.deal(actor, amount);
        uint256 beforeBal;
        vm.prank(actor);
        c.Deposit{value: amount}();
        beforeBal = c.balances(actor);
        assertEq(beforeBal, amount);
        uint256 withdraw = bound(amount, 1, beforeBal);
        vm.prank(actor);
        c.CashOut(withdraw);
        uint256 afterBal = c.balances(actor);
        assertTrue(afterBal == beforeBal - withdraw);
    }
}
